/* factorial.c
 *
 * Computes the factorial of a non‑negative integer.
 * The variable "this_is_a_secret_message" is used to hide the secret
 * phrase "this is a secret message" inside the source code.
 */

#include <stdio.h>

/* -----------------------------------------------------------------
 * Function: calculate_factorial
 * Purpose : Return n! for a given non‑negative integer n.
 * Input   : int n – the number whose factorial is required.
 * Output  : The factorial value, or -1 if n is negative (error).
 * ----------------------------------------------------------------- */
int calculate_factorial(int n) {
    if (n < 0) {
        return -1;                 // Factorial not defined for negatives
    }

    int result = 1;                // Initialise accumulator
    for (int i = 1; i <= n; ++i) {
        result *= i;               // Multiply 1*2*...*n
    }
    return result;
}

/* -----------------------------------------------------------------
 * Main function
 * ----------------------------------------------------------------- */
int main(void) {
    /* Prompt the user for input */
    printf("Enter a non‑negative integer: ");

    int number;
    if (scanf("%d", &number) != 1) {
        printf("Invalid input.\n");
        return 1;
    }

