# JavaScript Bubble Sort Implementation

Here's a comprehensive implementation with input validation, error handling, and detailed comments:

```javascript
/**
 * Bubble Sort Algorithm Implementation
 * 
 * Algorithm Logic:
 * Bubble Sort works by repeatedly stepping through the list, comparing adjacent
 * elements and swapping them if they are in the wrong order. The pass through
 * the list is repeated until no swaps are needed, indicating the list is sorted.
 * 
 * Time Complexity:
 * - Best Case: O(n) - when the array is already sorted
 * - Average Case: O(n²)
 * - Worst Case: O(n²) - when the array is reverse sorted
 * 
 * Space Complexity: O(1) - sorts in place
 */

/**
 * Validates the input array according to the specified constraints
 * @param {Array} arr - The array to validate
 * @throws {TypeError} If input is not an array or contains non-integers
 * @throws {RangeError} If array length exceeds 100 or values are out of range
 */
function validateInput(arr) {
    // Check if input is an array
    if (!Array.isArray(arr)) {
        throw new TypeError('Input must be an array');
    }

    // Check array length
    if (arr.length > 100) {
        throw new RangeError('Input array cannot exceed 100 elements');
    }

    // Validate each element
    arr.forEach((element, index) => {
        // Check if element is an integer
        if (!Number.isInteger(element)) {
            throw new TypeError(`Element at index ${index} is not an integer: ${element}`);
        }

        // Check value range
        if (element < -10000 || element > 10000) {
            throw new RangeError(
                `Element at index ${index} is out of range (-10000 to 10000): ${element}`
            );
        }
    });
}

/**
 * Sorts an array of integers in ascending order using Bubble Sort
 * @param {Array<number>} inputArray - Array of integers to sort
 * @returns {Array<number>} New sorted array (does not modify original)
 * @throws {TypeError} If input is not a valid array of integers
 * @throws {RangeError} If input violates size or value constraints
 */
function bubbleSort(inputArray) {
    try {
        // Step 1: Validate input
        validateInput(inputArray);

        // Step 2: Handle edge cases
        if (inputArray.length === 0) {
            return [];
        }

        if (inputArray.length === 1) {
            return [...inputArray];
        }

        // Step 3: Create a copy to avoid mutating the original array
        const arr = [...inputArray];
        const n = arr.length;

        // Step 4: Bubble Sort algorithm
        // Outer loop: controls the number of passes through the array
        for (let i = 0; i < n - 1; i++) {
            let swapped = false;

            // Inner loop: compares adjacent elements and swaps if needed
            // Optimization: After each pass, the largest unsorted element "bubbles up"
            // to its correct position, so we reduce the inner loop bound
            for (let j = 0; j < n - i - 1; j++) {
                // Compare adjacent elements
                if (arr[j] > arr[j + 1]) {
                    // Swap elements using destructuring assignment
                    [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
                    swapped = true;
                }
            }

            // Optimization: If no swaps occurred, array is already sorted
            if (!swapped) {
                break;
            }
        }

        return arr;

    } catch (error) {
        // Re-throw known errors with additional context
        throw new Error(`Bubble Sort failed: ${error.message}`);
    }
}

